{"read_file": """"Shared data + validation infrastructure for factor mining (warm-up 2020-01-01..2026-07-15).

Usage:
    from miner1_20260716_lib import build_panel, validate_factor
"""
import numpy as np
import pandas as pd
from alphacrafter.sim.utils import get_stock_daily_data, get_index_daily_data

WATCH = ['000300.SH', 'SPX', 'HSI', 'N225', 'SX5E', '000688.SH', 'SOX', 'NDX',
         'XAU', 'COPPER', 'WTI', 'BTC', 'ETH', 'US10Y', 'CN10Y']
MACRO = ['DXY', 'USDCNY', 'USDJPY', 'EURUSD', 'VIX']
WARMUP_END = pd.Timestamp('2026-07-15')
DATA_START = pd.Timestamp('2020-01-01')


def _fetch(sym, days=4000):
    try:
        df = get_stock_daily_data(symbol=sym, days=days)
    except Exception:
        df = get_index_daily_data(symbol=sym, days=days)
    if df is None or len(df) == 0:
        return None
    df = df.copy()
    df['date'] = pd.to_datetime(df['date'])
    df = df[(df['date'] >= DATA_START) & (df['date'] <= WARMUP_END)].sort_values('date')
    df = df.set_index('date')
    return df


def load_macro():
    out = {}
    for m in MACRO:
        df = pd.read_csv(f'../persistent/index_data/{m}.csv')
        df['date'] = pd.to_datetime(df['date'])
        df = df[(df['date'] >= DATA_START) & (df['date'] <= WARMUP_END)].sort_values('date')
        out[m] = df.set_index('date')['close'].astype(float)
    return out


def build_panel():
    """Return dict of per-asset DataFrames (close/volume on native calendars) and union grid."""
    closes, volumes = {}, {}
    for sym in WATCH:
        df = _fetch(sym)
        if df is None:
            continue
        closes[sym] = df['close'].astype(float)
        if 'volume' in df.columns:
            volumes[sym] = df['volume'].astype(float)
    macro = load_macro()
    grid = pd.DatetimeIndex(sorted(set().union(*[set(c.index) for c in closes.values()])))
    return {'closes': closes, 'volumes': volumes, 'macro': macro, 'grid': grid}


def factor_values(closes, volumes, grid, fn):
    """fn(sym, close_series, volume_series) -> factor series on native calendar."""
    out = pd.DataFrame(index=grid)
    for sym in closes:
        try:
            v = fn(sym, closes[sym], volumes.get(sym))
            if v is not None and len(v) > 0:
                out[sym] = v.reindex(grid)
        except Exception:
            continue
    return out


def forward_returns(closes, grid, horizon):
    """Forward h-day return per asset on native calendar, reindexed to grid."""
    out = pd.DataFrame(index=grid)
    for sym, s in closes.items():
        fwd = s.shift(-horizon) / s - 1.0
        out[sym] = fwd.reindex(grid)
    return out


def daily_ic(factor_frame, ret_frame, min_valid=8, method='spearman'):
    """Cross-sectional IC per date."""
    idx = factor_frame.index.intersection(ret_frame.index)
    ics = []
    for d in idx:
        f = factor_frame.loc[d]
        r = ret_frame.loc[d]
        mask = f.notna() & r.notna()
        n = int(mask.sum())
        if n < min_valid:
            continue
        fv, rv = f[mask].astype(float), r[mask].astype(float)
        if fv.nunique() < 2 or rv.nunique() < 2:
            continue
        if method == 'spearman':
            ic = fv.rank().corr(rv.rank())
        else:
            ic = fv.corr(rv)
        if np.isfinite(ic):
            ics.append((d, ic, n))
    return pd.DataFrame(ics, columns=['date', 'ic', 'n']).set_index('date')


def summarize(ics, label, horizon, turnover=None, coverage=None):
    if len(ics) == 0:
        print(f"[{label}] NO VALID IC DATES")
        return None
    ic = ics['ic']
    mean_ic = float(ic.mean())
    std_ic = float(ic.std(ddof=1)) if len(ic) > 1 else float('nan')
    icir = mean_ic / std_ic if std_ic and np.isfinite(std_ic) and std_ic > 0 else float('nan')
    hit = float((ic > 0).mean())
    med_n = int(ics['n'].median())
    turn_s = f"{turnover:.3f}" if turnover is not None else "nan"
    cov_s = f"{coverage:.3f}" if coverage is not None else "nan"
    print(f"[{label}] h={horizon} dates={len(ic)} med_n={med_n} "
          f"IC={mean_ic:+.4f} ICIR={icir:+.3f} hit={hit:.2f} "
          f"turn={turn_s} cov={cov_s}")
    return {'label': label, 'horizon': horizon, 'dates': len(ic), 'median_n': med_n,
            'ic': mean_ic, 'icir': icir, 'hit': hit, 'std': std_ic}


def validate_factor(label, fn, horizons=(1, 2, 3, 5, 10, 20), min_valid=8):
    """fn(sym, close, volume) -> factor series. Validates across horizons, reports decay."""
    panel = build_panel()
    closes, volumes, grid = panel['closes'], panel['volumes'], panel['grid']
    fac = factor_values(closes, volumes, grid, fn)
    cov = float(fac.notna().mean().mean())
    rank = fac.rank(axis=1)
    turn = float(rank.diff().abs().mean().mean()) if len(rank) > 1 else float('nan')
    print(f"[{label}] factor frame shape={fac.shape} coverage={cov:.3f} avg_turnover={turn:.3f}")
    results = {}
    for h in horizons:
        ret = forward_returns(closes, grid, h)
        ics = daily_ic(fac, ret, min_valid=min_valid)
        res = summarize(ics, label, h, turnover=turn, coverage=cov)
        results[h] = res
    return panel, fac, results


def decay_table(results):
    print("\nDECAY: ", " | ".join(f"h={h}: IC={r['ic']:+.4f} ICIR={r['icir']:+.3f}" for h, r in results.items()))


def regime_breakdown(ics, panel, label):
    if len(ics) == 0:
        return
    t = ics.copy()
    t['year'] = t.index.year
    print(f"\n[{label}] IC by year:")
    for y, g in t.groupby('year'):
        s = g['ic'].std(ddof=1)
        icir = g['ic'].mean() / s if s and np.isfinite(s) and s > 0 else float('nan')
        print(f"  {y}: dates={len(g)} IC={g['ic'].mean():+.4f} ICIR={icir:+.3f}")
    vix = panel['macro'].get('VIX')
    if vix is not None:
        v = vix.reindex(t.index)
        q = v.quantile([0.33, 0.66])
        lo, hi = q.iloc[0], q.iloc[1]
        for nm, mask in [('VIX_low', v <= lo), ('VIX_mid', (v > lo) & (v <= hi)), ('VIX_high', v > hi)]:
            g = t[mask.values]
            if len(g):
                s = g['ic'].std(ddof=1)
                icir = g['ic'].mean() / s if s and np.isfinite(s) and s > 0 else float('nan')
                print(f"  {nm}: dates={len(g)} IC={g['ic'].mean():+.4f} ICIR={icir:+.3f}")
"}

{"read_file": """"miner_1 batch-2: explore macro-conditional (DXY/VIX beta), vol term structure,
skewness, z-score reversion, close-position, autocorrelation, volume trend.

Admission gate at h=10: |IC| >= 0.007 and |ICIR| >= 0.084.
Also prints coverage, 10-day-rebalance rank turnover, and pairwise correlation
with already-passing batch-1 candidates.
"""
import numpy as np
import pandas as pd
from miner1_20260716_lib import (build_panel, factor_values, forward_returns,
                                 daily_ic, summarize)

H = 10
MIN_VALID = 8


def _ret(close):
    return close.pct_change()


def vol_ratio_short_long(short=20, long=120):
    def fn(sym, close, volume):
        vs = _ret(close).rolling(short).std()
        vl = _ret(close).rolling(long).std()
        return (1.0 - vs / vl).replace([np.inf, -np.inf], np.nan)  # high=calm
    return fn


def drawdown_dist(win=60):
    def fn(sym, close, volume):
        return 1.0 - close / close.rolling(win).max()
    return fn


def ret_skew(win=60):
    def fn(sym, close, volume):
        return _ret(close).rolling(win).skew()
    return fn


def autocorr_ret(win=60, lag=5):
    def fn(sym, close, volume):
        r = _ret(close)
        a = r.rolling(win).apply(lambda x: x.autocorr(lag) if len(x) == win else np.nan, raw=False)
        return a
    return fn


def zscore_rev(win=20):
    def fn(sym, close, volume):
        ma = close.rolling(win).mean()
        sd = _ret(close).rolling(win).std() * close
        return ((close - ma) / sd).replace([np.inf, -np.inf], np.nan)
    return fn


def inv_vol(win=60):
    def fn(sym, close, volume):
        sd = _ret(close).rolling(win).std()
        return (-sd).replace([np.inf, -np.inf], np.nan)
    return fn


def downside_ratio(win=60):
    def fn(sym, close, volume):
        r = _ret(close)
        dd = r.clip(upper=0).rolling(win).std()
        v = r.rolling(win).std()
        return (dd / v).replace([np.inf, -np.inf], np.nan)
    return fn


def volume_trend(short=5, long=60):
    def fn(sym, close, volume):
        if volume is None or volume.dropna().empty:
            return None
        v = volume.astype(float)
        return (v.rolling(short).mean() / v.rolling(long).mean()).replace([np.inf, -np.inf], np.nan)
    return fn


def macro_beta_cond(macro_key, sign=-1.0, win=60, mom=20):
    """factor = sign * rolling_beta(asset_ret, macro_ret) * macro_momentum."""
    def fn(sym, close, volume, panel=None):
        if panel is None:
            return None
        macro = panel['macro'].get(macro_key)
        if macro is None:
            return None
        grid = panel['grid']
        r_a = close.pct_change().reindex(grid)
        r_m = macro.pct_change().reindex(grid)
        beta = r_a.rolling(win, min_periods=30).cov(r_m) / r_m.rolling(win, min_periods=30).var()
        mm = (macro.reindex(grid) / macro.shift(mom).reindex(grid) - 1.0)
        return (sign * beta * mm).replace([np.inf, -np.inf], np.nan)
    return fn


CANDIDATES = [
    ('mom_60d_skip5', lambda sym, c, v: c.shift(5) / c.shift(65) - 1.0),
    ('vol_term_20_120', vol_ratio_short_long(20, 120)),
    ('drawdown_60d', drawdown_dist(60)),
    ('ret_skew_60d', ret_skew(60)),
    ('zscore_rev_20d', zscore_rev(20)),
    ('inv_vol_60d', inv_vol(60)),
    ('downside_ratio_60d', downside_ratio(60)),
    ('autocorr_60d_5lag', autocorr_ret(60, 5)),
    ('volume_trend_5_60', volume_trend(5, 60)),
    ('dxy_beta_cond_60x20', macro_beta_cond('DXY', sign=-1.0)),
    ('vix_beta_cond_60x20', macro_beta_cond('VIX', sign=-1.0)),
]


def with_panel(fn, panel):
    """Wrap factor fn to receive panel for macro-conditional candidates."""
    def wrapped(sym, close, volume):
        return fn(sym, close, volume, panel=panel)
    return wrapped


if __name__ == '__main__':
    panel = build_panel()
    closes, volumes, grid = panel['closes'], panel['volumes'], panel['grid']
    ret = forward_returns(closes, grid, H)

    # batch-1 passing library for correlation reference
    lib1 = {
        'mom_10d_skip5': lambda s, c, v: c.shift(5) / c.shift(15) - 1.0,
        'mom_20d_skip5': lambda s, c, v: c.shift(5) / c.shift(25) - 1.0,
        'mom_120d_skip5': lambda s, c, v: c.shift(5) / c.shift(125) - 1.0,
        'trend_sma60': lambda s, c, v: c / c.rolling(60).mean() - 1.0,
        'trend_sma120': lambda s, c, v: c / c.rolling(120).mean() - 1.0,
        'risk_adj_trend20': lambda s, c, v: (c.pct_change().rolling(20).mean()
                                             / c.pct_change().rolling(20).std()
                                             ).replace([np.inf, -np.inf], np.nan),
        'vol_of_vol20x60': lambda s, c, v: c.pct_change().rolling(20).std().rolling(60).std(),
    }
    lib_frames = {}
    for lbl, fn in lib1.items():
        lib_frames[lbl] = factor_values(closes, volumes, grid, fn)

    results = {}
    new_frames = {}
    print(f'=== BATCH-2 VALIDATION h={H} ===')
    for label, fn in CANDIDATES:
        ffn = with_panel(fn, panel) if label in ('dxy_beta_cond_60x20', 'vix_beta_cond_60x20') else fn
        fac = factor_values(closes, volumes, grid, ffn)
        new_frames[label] = fac
        cov_assets = float(fac.notna().mean().mean())
        cov_dates = float((fac.notna().sum(axis=1) >= MIN_VALID).mean())
        f10 = fac.iloc[::10]
        turn = float(f10.rank(axis=1).diff().abs().mean().mean()) if len(f10) > 2 else np.nan
        ics = daily_ic(fac, ret, min_valid=MIN_VALID)
        m = summarize(ics, label, H)
        m['coverage_assets'] = cov_assets
        m['coverage_dates8'] = cov_dates
        m['turnover'] = turn
        results[label] = m
        print(f'   cov_assets={cov_assets:.3f} cov_dates8+={cov_dates:.3f} turn={turn:.3f}')

    print('\n=== YEARLY IC (h=10) for batch-2 ===')
    for label, fac in new_frames.items():
        ics = daily_ic(fac, ret, min_valid=MIN_VALID)
        if len(ics) == 0:
            continue
        s = ics['ic']
        print(f'[{label}]', {int(y): round(float(v), 4) for y, v in s.groupby(s.index.year).mean().items()})

    print('\n=== PAIRWISE CORR (new vs batch-1 library) ===')
    all_labels = list(lib_frames.keys()) + list(new_frames.keys())
    corr = pd.DataFrame(index=all_labels, columns=all_labels, dtype=float)
    cd = None
    for l in all_labels:
        d = lib_frames[l].dropna(how='all').index if l in lib_frames else new_frames[l].dropna(how='all').index
        cd = d if cd is None else cd.intersection(d)
    for i, a in enumerate(all_labels):
        for j, b in enumerate(all_labels):
            if i > j:
                continue
            fa = lib_frames[a] if a in lib_frames else new_frames[a]
            fb = lib_frames[b] if b in lib_frames else new_frames[b]
            cs = []
            for t in cd:
                x, y = fa.loc[t], fb.loc[t]
                mask = x.notna() & y.notna() & np.isfinite(x) & np.isfinite(y)
                if mask.sum() >= 8:
                    r = pd.Series(x[mask]).corr(pd.Series(y[mask]), method='spearman')
                    if np.isfinite(r):
                        cs.append(r)
            v = float(np.mean(cs)) if cs else np.nan
            corr.loc[a, b] = v
            corr.loc[b, a] = v
    pd.set_option('display.width', 250)
    print(corr.round(2))
"}

{"read_file": """"Factor family: trend (price vs moving average), risk-adjusted trend, vol, drawdown, efficiency."""
import numpy as np
from miner1_20260716_lib import validate_factor, decay_table, forward_returns, daily_ic, regime_breakdown


def make_trend(win):
    def fn(sym, close, volume):
        ma = close.rolling(win).mean()
        return close / ma - 1.0
    return fn


def risk_adj_trend(win=20):
    def fn(sym, close, volume):
        ret = close.pct_change()
        mu = ret.rolling(win).mean()
        sd = ret.rolling(win).std()
        return (mu / sd).replace([np.inf, -np.inf], np.nan)
    return fn


def inv_vol(win=20):
    def fn(sym, close, volume):
        sd = close.pct_change().rolling(win).std()
        return (-sd).replace([np.inf, -np.inf], np.nan)
    return fn


def drawdown_dist(win=60):
    def fn(sym, close, volume):
        return 1.0 - close / close.rolling(win).max()
    return fn


def efficiency_ratio(win=60):
    def fn(sym, close, volume):
        net = (close - close.shift(win)).abs()
        path = close.diff().abs().rolling(win).sum()
        return (net / path).replace([np.inf, -np.inf], np.nan)
    return fn


def vol_of_vol(win=20, sub=60):
    def fn(sym, close, volume):
        sd = close.pct_change().rolling(win).std()
        return sd.rolling(sub).std()
    return fn


if __name__ == '__main__':
    candidates = [
        ('trend_sma20', make_trend(20)),
        ('trend_sma60', make_trend(60)),
        ('trend_sma120', make_trend(120)),
        ('risk_adj_trend20', risk_adj_trend(20)),
        ('inv_vol20', inv_vol(20)),
        ('drawdown_60d', drawdown_dist(60)),
        ('efficiency_60d', efficiency_ratio(60)),
        ('vol_of_vol', vol_of_vol()),
    ]
    for label, fn in candidates:
        panel, fac, results = validate_factor(label, fn, min_valid=8)
        decay_table(results)
        ret = forward_returns(panel['closes'], panel['grid'], 5)
        ics = daily_ic(fac, ret, min_valid=8)
        regime_breakdown(ics, panel, label)
        print('=' * 80)
"}

{"read_file": """"miner_1: compute passing candidates' h=10 metrics + pairwise cross-sectional
rank correlation to plan a diverse, non-redundant factor library."""
import numpy as np
import pandas as pd
from miner1_20260716_lib import (build_panel, factor_values, forward_returns,
                                 daily_ic, summarize)


def make_mom(lookback, skip=5):
    def fn(sym, close, volume):
        return close.shift(skip) / close.shift(skip + lookback) - 1.0
    return fn


def make_trend(win):
    def fn(sym, close, volume):
        ma = close.rolling(win).mean()
        return close / ma - 1.0
    return fn


def risk_adj_trend(win=20):
    def fn(sym, close, volume):
        ret = close.pct_change()
        mu = ret.rolling(win).mean()
        sd = ret.rolling(win).std()
        return (mu / sd).replace([np.inf, -np.inf], np.nan)
    return fn


def vol_of_vol(win=20, sub=60):
    def fn(sym, close, volume):
        sd = close.pct_change().rolling(win).std()
        return sd.rolling(sub).std()
    return fn


def efficiency_ratio(win=60):
    def fn(sym, close, volume):
        net = (close - close.shift(win)).abs()
        path = close.diff().abs().rolling(win).sum()
        return (net / path).replace([np.inf, -np.inf], np.nan)
    return fn


CANDIDATES = [
    ('mom_10d_skip5', make_mom(10)),
    ('mom_20d_skip5', make_mom(20)),
    ('mom_120d_skip5', make_mom(120)),
    ('trend_sma60', make_trend(60)),
    ('trend_sma120', make_trend(120)),
    ('risk_adj_trend20', risk_adj_trend(20)),
    ('vol_of_vol20x60', vol_of_vol()),
    ('efficiency_60d', efficiency_ratio(60)),
]

if __name__ == '__main__':
    panel = build_panel()
    closes, volumes, grid = panel['closes'], panel['volumes'], panel['grid']
    h = 10
    ret = forward_returns(closes, grid, h)
    frames, metrics = {}, {}
    print('=== H=10 VALIDATION (admission gate |IC|>=0.007, |ICIR|>=0.084) ===')
    for label, fn in CANDIDATES:
        fac = factor_values(closes, volumes, grid, fn)
        frames[label] = fac
        ics = daily_ic(fac, ret, min_valid=8)
        m = summarize(ics, label, h)
        metrics[label] = m

    print('\n=== PAIRWISE CROSS-SECTIONAL RANK CORRELATION (mean over dates) ===')
    labels = [l for l, _ in CANDIDATES]
    corr = pd.DataFrame(index=labels, columns=labels, dtype=float)
    common_dates = None
    for l in labels:
        d = frames[l].dropna(how='all').index
        common_dates = d if common_dates is None else common_dates.intersection(d)
    for i, a in enumerate(labels):
        for j, b in enumerate(labels):
            if i > j:
                continue
            cs = []
            for t in common_dates:
                fa, fb = frames[a].loc[t], frames[b].loc[t]
                mask = fa.notna() & fb.notna() & np.isfinite(fa) & np.isfinite(fb)
                if mask.sum() >= 8:
                    r = pd.Series(fa[mask]).corr(pd.Series(fb[mask]), method='spearman')
                    if np.isfinite(r):
                        cs.append(r)
            v = float(np.mean(cs)) if cs else np.nan
            corr.loc[a, b] = v
            corr.loc[b, a] = v
    pd.set_option('display.width', 200)
    print(corr.round(3))
    print(f'\ncommon dates used: {len(common_dates)}')
"}

